import{_ as e,c as s,o,ae as i}from"./chunks/framework.CHDT0Kbg.js";const h=JSON.parse('{"title":"Privacidad y tus datos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy.md","filePath":"es/guide/privacy.md","lastUpdated":1795170900000}'),r={name:"es/guide/privacy.md"};function t(c,a,n,d,l,u){return o(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="privacidad-y-tus-datos" tabindex="-1">Privacidad y tus datos <a class="header-anchor" href="#privacidad-y-tus-datos" aria-label="Permalink to &quot;Privacidad y tus datos&quot;">​</a></h1><p>Qué se queda en tu Mac y cuándo hace falta la red.</p><h2 id="guardado-en-tu-mac" tabindex="-1">Guardado en tu Mac <a class="header-anchor" href="#guardado-en-tu-mac" aria-label="Permalink to &quot;Guardado en tu Mac&quot;">​</a></h2><p>El historial, los marcadores, las pestañas abiertas, las descargas y las cookies se guardan localmente. No hay cuenta ni sincronización en la nube. Una ventana privada (⌘⇧N) no deja historial ni sesión.</p><h2 id="cuando-se-usa-la-red" tabindex="-1">Cuándo se usa la red <a class="header-anchor" href="#cuando-se-usa-la-red" aria-label="Permalink to &quot;Cuándo se usa la red&quot;">​</a></h2><ul><li>Al cargar los sitios que visitas, por supuesto.</li><li>Al actualizar una suscripción de bloqueo de anuncios, si está activada. Si falla, las reglas guardadas siguen funcionando.</li><li>Al descargar un script o un archivo que hayas pedido.</li></ul><h2 id="tus-permisos" tabindex="-1">Tus permisos <a class="header-anchor" href="#tus-permisos" aria-label="Permalink to &quot;Tus permisos&quot;">​</a></h2><p>El acceso a cámara y micrófono se recuerda por sitio. La ubicación y las notificaciones las controla macOS. Las ventanas emergentes se limitan a los sitios que permites.</p><h2 id="archivos-en-disco" tabindex="-1">Archivos en disco <a class="header-anchor" href="#archivos-en-disco" aria-label="Permalink to &quot;Archivos en disco&quot;">​</a></h2><p>Persim solo lee archivos que eliges en el diálogo del sistema o a los que das acceso explícitamente. Puedes revisar y revocar esos permisos en Ajustes.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h2><p>Preguntas sobre privacidad: <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',12)])])}const m=e(r,[["render",t]]);export{h as __pageData,m as default};
